Behavior::~TDragDropBehavior(){}//----------------------------------------------------------------------------------------// TDragDropBehavior::ReadFrom //----------------------------------------------------------------------------------------void TDragDropBehavior::ReadFrom(CStream_AC* aStream){	Inherited::ReadFrom(aStream);	fDraggable = aStream->ReadBoolean();	fDroppable = aStream->ReadBoolean();	fDragMoveDeterminer = aStream->ReadInteger();	fDragMoveFamily = aStream->ReadIDType();}//----------------------------------------------------------------------------------------// TDragDropBehavior::WriteTo//----------------------------------------------------------------------------------------void TDragDropBehavior::WriteTo(CStream_AC* aStream) const{	Inherited::WriteTo(aStream);	#if qDrag	// read drag data out of the owner, since the values in the behavior may not be	// current	{		TView *ownerView = dynamic_cast_or_throw_AC(TView*,fOwner);			const_cast<TDragDropBehavior*>(this)->fDraggable = ownerView->GetDraggable();		const_cast<TDragDropBehavior*>(this)->fDroppable = ownerView->GetDroppable();		const_cast<TDragDropBehavior*>(this)->fDragMoveDeterminer = ownerView->GetDragMoveDeterminer();		const_cast<TDragDropBehavior*>(this)->fDragMoveFamily = ownerView->GetDragMoveFamily();	}#endif // qDrag	aStream->WriteBoolean(fDraggable);	aStream->WriteBoolean(fDroppable);	aStream->WriteInteger(fDragMoveDeterminer);	aStream->WriteIDType(fDragMoveFamily);}//----------------------------------------------------------------------------------------// TDragDropBehavior::SetOwner//----------------------------------------------------------------------------------------void TDragDropBehavior::SetOwner(TEventHandler* itsOwner){	Inherited::SetOwner(itsOwner);	#if qDrag#if qDebug	// verify that the owner is a TView		if (itsOwner && !dynamic_cast_AC(TView*,itsOwner))	{		::ProgramBreak_AC("###A TDragDropBehavior is attached to a non-view object");		return;	}#endif // qDebug	// set data in the owner view	if (itsOwner)	{		TView *ownerView = dynamic_cast_or_throw_AC(TView*,itsOwner);				ownerView->SetDraggable(fDraggable);		ownerView->SetDroppable(fDroppable);		ownerView->SetDragMoveDeterminer(fDragMoveDeterminer);		ownerView->SetDragMoveFamily(fDragMoveFamily);	}#endif // qDrag}//----------------------------------------------------------------------------------------// TDragDropBehavior::GetStandardSignature://----------------------------------------------------------------------------------------IDType TDragDropBehavior::GetStandardSignature() const{	return kDragDropBehavior;}//----------------------------------------------------------------------------------------// End of UDragDropBehavior.cpp/*	Historical Change Record:		----- R11 -----		06/26/96	Install release marker.  Scope many globals.  Change TRUE/FALSE/NULL.		06/09/96	Removed UStreamable to a separate file from UObject		04/30/96	Make all constructors use initialization lists if they weren't already							doing do. Switch several more empty constructors to inlines.		----- R10 -----		12/08/95	Split up includes for modular MacApp. 		----- 3.3 -----		10/11/95	Add TDragDropBehavior::GetStandardSignature.		 					TDragDropBehavior::SetOwner tests fOwner before using.		----- 3.3b1 -----		09/01/95	Change MADragSeg to MADragNonRes.		07/28/95	Add configuration functions to use instead of gConfiguration. 		03/28/95	Changed dragMoveZone to dragMoveDeterminer.		03/17/95	Remove constrainToWindow and constrainToScroller.		 					Add fDragMoveFamily and fDragMoveZone.		03/13/95	Change Free methods to destructors. 		02/17/95	Don't access view if qDrag is false. 		01/04/95	Removed references to qDrag. The linker will decide when and							when not to strip this unit.							Removed include of UWindow. Added include of UView.							TDragDropBehavior::Free doesn't unregister the behavior							from the window.							Property accessors were removed. They are no longer useful.							Removed TDragDropBehavior::Free.  The inherited version will do fine.		01/04/95	Began changing TDragDropBehavior to dispose itself							after setting data in the owner view, and to support							recreation when writing out to a stream.		----- 3.5d3 Release -----		12/15/94	Adjusted qDrag conditional to leave							TDragDropBehavior::Write in if qDrag is false.		11/13/94	If qDrag is false, TDragDropBehavior exists as a							functionless stub.		11/11/94	Test gConfiguration.hasDragManager() at runtime							before attempting to register or unregister							with the associated window.		11/11/94	Conditionally compile this unit out if qDrag is							false.		10/17/94	Initialized UDragDrop.cp. Moved all drag manager							calls into that unit.  Removed all subclasses of							TDragDropBehavior. Moved view-specific drag support							into appropriate subclasses of TView.		10/03/94	Add gDragSendDataUPP. Added code to initialize							gDragSendDataUPP.  Add DragSendDataProcGlue,							which calls the actual TDragDropBehavior::DragSendDataProc.							TDragDropBehavior::DragSendDataProc was declared static pascal.							It is now virtual, and no longer uses pascal calling convention.							It can now be overriden by subclasses, and will be invoked by							the glue routine.  Removed refCon parameter from DragSendDataProc,							since it is no longer static and can use "this".		09/28/94	Change DropLocationIsFinderTrash(AEDesc& desc) to							DropLocationIsFinderTrash(CAEDesc_AC& desc).							Change GetDropLocationDirectory to take CAEDesc_AC as a							parameter and to pass references, instead of pointers,							to the dirID and vRefNum parameters.							Change TBehavior::DoMouseCommand to use CTempDesc_AC for							local AEDesc vars.		09/12/94	Merged with MacApp project as part of Eric							Hanig's MacApp additions.*/